mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM fgc.agent
     WHERE agent_id = #{agentId}
)

SELECT EXISTS (
    SELECT 1
      FROM fgc.agent
     WHERE agent_id = #{agentId}
       AND active_yn = TRUE
       AND newcomer_support_eligible_yn = TRUE
       AND prior_three_year_experience_yn = FALSE
       AND newcomer_support_end_date >= #{asOfDate}
)

SELECT appointment_date
  FROM fgc.agent
 WHERE agent_id = #{agentId}

SELECT COUNT(*)
  FROM fgc.insurance_contract
 WHERE agent_id = #{agentId}
   AND contract_date < #{monthStart}

SELECT allocation_policy_id
  FROM fgc.allocation_policy
 WHERE policy_version_id = #{policyVersionId}
   AND allocation_basis_code = #{allocationBasis}
 ORDER BY allocation_policy_id
 LIMIT 1

SELECT EXISTS (
    SELECT 1
      FROM fgc.policy_version
     WHERE policy_version_id = #{policyVersionId}
       AND status IN ('APPROVED', 'ACTIVE')
)
